      dict(id='opt-qf905', rank=4, label='Qantas QF905 Sunshine Coast → Sydney, 7am (safest from MCY)', route='MCY → SYD T3', date='2027-02-08', dep='07:00', arr='09:50', duration='1h40', cashAud=150, points=9200, pointsTaxAud=58, status='skip', notes='Lowest risk if you insist on MCY: a whole day of fallback options. Long day in Sydney though (8+ hours in the lounge).'),
