      dict(id='opt-jq10', rank=4, label='Jetstar JQ10 Narita → Brisbane, economy', route='NRT → BNE', date='2027-02-16', dep='20:50', arr='06:45', duration='8h55', cashAud=409, priceNote='from ~A$409 + bag/meal', points=24000, pointsTaxAud=110, status='idea', notes='Cheapest points option (Jetstar table, ~24,000 pts est.; includes 20 kg bag). 787, no PE; you can bid for Jetstar Business with points + cash.'),
      dict(id='opt-jq24', rank=5, label='Jetstar JQ24 Osaka KIX → Brisbane (only if the trip is flipped to end in Osaka)', route='KIX → BNE', date='2027-02-16', dep='21:45', arr='07:25', duration='8h45', cashAud=420, priceNote='from ~A$400', points=24000, pointsTaxAud=110, status='idea', notes='Runs ~4x weekly; confirm Monday operates. Would let you do USJ on the last day and skip the Tokyo backtrack, at the cost of USJ on a Monday instead of Wednesday.'),
      dict(id='opt-qf80', rank=0, label='QF80 Narita → Melbourne 19:20 + QF1256 Melbourne → Brisbane 09:20 (BOOKED, cash Economy Sale)', route='NRT → MEL → BNE', date='2027-02-16', dep='19:20', arr='10:35', duration='10h25 + 1h35 change + 2h15', cashAud=857, priceNote='¥92,570 paid', status='booked', notes='Booked as a paid Economy Sale fare (QF62 had no reward seats). Consequences: no points upgrade is possible on a Sale fare, so the 164k points stay in the bank for another trip; Economy Plus extra legroom may still be added in Manage Booking. 1h35 in Melbourne is protected because both flights are on one booking. Lands Brisbane 10:35 Wed, home early afternoon.'),
      dict(id='opt-qf26', rank=6, label='QF26 Haneda → Sydney, the only flight with Premium Economy', route='HND → SYD', date='2027-02-17', dep='06:55', arr='18:55', duration='~10h', cashAud=900, priceNote='economy cash est.', points=36200, pointsTaxAud=140, status='idea', notes='3-class A330 from Oct 2026. Economy ~36,200 pts est., PE ~74,000 pts est. Departs 6:55am (check-in from 4am, before trains run), so you would sleep at a Haneda hotel on the 15th and then still need SYD → Brisbane/Sunshine Coast. Only worth it if PE is the priority over everything else.'),
