questions = [
  dict(id='q1', question='Ski base: Nozawa Onsen, Myoko (Akakura Onsen) or Hakuba?', why='You said “south island”, which does not exist for skiing (Japan’s ski areas are on Hokkaido in the north and in the Nagano/Niigata mountains on the main island). Given Narita arrival + Osaka + a week, Nagano/Niigata is the only sensible region. Nozawa is the closest thing to Banff: a real village, walkable, hot springs, mountain rising straight off it, local food. It is also the most Australian of the villages and the busiest over the 11-14 Feb long weekend.', options=['Nozawa Onsen (planned): Banff-like village, big mountain, local food, busiest and priciest of the three that weekend', 'Myoko / Akakura Onsen: quieter, cheaper, more Japanese, 13-16 m of snow, smaller mountain, fiddlier buses', 'Hakuba: biggest terrain and most Banff-like scale, but a sprawl of villages linked by buses and very international'], recommendation='Nozawa Onsen. If you decide “not hyped” matters more than terrain, switch to Myoko: the plan only changes at the Nagano end (Shinkansen to Joetsu-Myoko instead of Iiyama).', answer='Nozawa sounds good', resolved=True),
  dict(id='q2', question='Trip shape: Universal Studios first (Wednesday) or ski first and fly home from Osaka?', why='Wed 10 Feb is the only calm weekday for USJ in the window (Thu 11 is a public holiday and the weekend follows, plus the tail of Lunar New Year travel). That forces the skiing onto the long weekend. The alternative is ski Wed-Fri (quieter slopes on Wed), then USJ on Mon 15 and fly Jetstar Osaka → Brisbane at 9:45pm that night, no Tokyo backtrack.', options=['USJ Wed 10, ski Fri-Mon, fly QF62 Narita → Brisbane Mon 15 (planned)', 'Ski Wed-Fri, Osaka Sat-Mon, USJ Mon 15, Jetstar JQ24 Osaka → Brisbane Mon 15 night'], recommendation='Keep USJ on the Wednesday. Super Nintendo World on a crowded day is the thing most likely to spoil the trip, and Nozawa is big enough to absorb a weekend if you start at 8:30. Monday morning skiing is the bonus.', answer='Ok sounds good. (And the flight home is now booked out of Narita, so ending in Osaka is no longer possible.)', resolved=True),
  dict(id='q3', question='Park at Brisbane or Sunshine Coast?', why='Decided by the booking: JQ815 departs Brisbane, and QF62 lands there. AIRPARK for 8-16 Feb.', options=['Brisbane (booked)'], recommendation='Brisbane.', answer='Ok sounds good. JQ815 booked 8 Feb 09:45.', resolved=True),
  dict(id='q4', question='How to use the points for the flight home?', why='Overtaken by events: QF62 had no reward seats, and QF80 + QF1256 was booked as a paid Economy Sale fare (¥92,570). Sale fares cannot be upgraded with points.', options=['Add Economy Plus extra legroom on QF80 in Manage Booking (cash or ~19,500 pts) if it is offered', 'Keep the ~164k points for the next trip'], recommendation='Try Economy Plus; otherwise bank the points.', answer='Booked cash Economy Sale on QF80 + QF1256.', resolved=True),
  dict(id='q5', question='What are the two “first class lounge passes”, exactly?', why='Answered: they are Qantas Money Titanium card First Lounge invitations. Valid at the Sydney, Melbourne and LA First Lounges on a QF/JQ flight, cardholder only.', options=['Use one at Melbourne T2 First Lounge on 8 Feb', 'Second one is unusable on this trip; keep it'], recommendation='Use one in Melbourne on 8 Feb; check the expiry in the Qantas app.', answer='Titanium credit card passes. One will be used in Melbourne; the other saved.', resolved=True),
  dict(id='q6', question='Rent ski gear or bring your own?', why='Rental in Nozawa is ~¥4,450-5,500 a day for skis, boots and poles, so 4 days is about A$165-200. Bringing skis means a 32 kg-allowance bag on the outbound (fine in Business) but hauling it through Tokyo Station, Osaka and two bus changes, plus the Shinkansen oversized-baggage rule.', options=['Rent everything in the village, bring only boots if you love yours (planned)', 'Bring skis and boots'], recommendation='Rent. This trip has too many trains for a ski bag. Bring your own boots only if fit is a problem for you.', answer='Rent in the village. The suitcase goes by courier and the itinerary has no room for a ski bag.', resolved=True),
  dict(id='q7', question='Fly home Monday 15 or Tuesday 16 Feb?', why='Decided: Tuesday 16. Monday becomes a full quiet ski day; the extra day costs about A$900 all-in.', options=['Tue 16: QF80 + QF1256 via Melbourne (booked)'], recommendation='Done.', answer='Tuesday 16 Feb, QF80 + QF1256 booked.', resolved=True),
  dict(id='q8', question='Keep this repo public?', why='The repo is public right now. That is why the app never writes booking references, ticket numbers or passport details to the repo (they live in the Private vault on your device). It is still safer to make the repo private since GitHub Pages works on private repos with a paid plan, or you can simply keep the rule: nothing sensitive in the plan text.', options=['Keep public, keep sensitive details in the vault only (current)', 'Make the repo private (Settings → General → Danger zone). Pages on private repos needs GitHub Pro.'], recommendation='Keep public for now and use the vault; revisit if you want to store confirmation emails in the repo.', answer='Keep public; sensitive details stay in the vault.', resolved=True),
  dict(id='q10', question='Give up Sunday’s skiing for Togakushi and Zenko-ji, or fly home Tuesday to keep three full ski days?', why='You asked for a rural day and said a ski day could go. Narai-juku is now built into Thursday’s travel day at no cost. Sunday is the worst ski day (long-weekend crowds), so it is the cheapest one to trade for Togakushi’s cedar avenue and Zenko-ji. That leaves Friday, Saturday and Monday morning on skis. Flying home Tuesday 16 instead would add a full quiet Monday on the slopes for about A$150 of lodging plus a day of leave.', options=['Sunday rural day, Monday morning ski, fly Mon 15 (planned)', 'Sunday rural day and fly Tue 16 so Monday is a full ski day', 'Keep skiing Sunday; rural Japan is just the Narai stop on Thursday'], recommendation='As planned, with the powder-day escape hatch: if Sunday dawns dumping, ski and skip Togakushi.', answer='Tue 16 is booked, so Monday is a full ski day and Sunday is the rural day, with the powder-day swap written into Sunday’s notes.', resolved=True),
  dict(id='q11', question='Which rural stop, if you want a different one?', why='Alternatives to Togakushi from Nozawa: Obuse (30 min from Nagano by Nagaden train, chestnut sweets, the Hokusai museum, sake brewery, old streets; easy and flat) or a dawn visit to Zenko-ji’s o-asaji morning service. Shirakawa-go’s farmhouses are the postcard but are 4+ hours each way from Nozawa and heavily touristed; not worth it on this trip. Matsumoto castle is a city.', options=['Togakushi + Zenko-ji (planned): mountain shrine, cedars, soba, snow walk', 'Obuse + Zenko-ji: gentler, indoor-heavy, good if the weather is foul', 'Nothing beyond Narai'], recommendation='Togakushi, with Obuse as the bad-weather substitute.', answer='Togakushi and Zenko-ji, with Obuse as the foul-weather substitute. Decide on the Saturday night.', resolved=True),
  dict(id='q9', question='Rough budget ceiling?', why='The plan currently totals roughly A$2,700-3,300 in cash on top of points, depending on Osaka hotel and the Express Pass. Knowing your ceiling decides whether to trade the ryokan half-board for a minshuku, and whether the Express Pass stays in.', options=['Under A$2,500: minshuku, skip Express Pass, Jetstar home', 'A$2,500-3,500: as planned', 'Over A$3,500: ryokan with dinner every night, Business home if available'], recommendation='As planned. The Express Pass is the one “splurge” that buys back a whole day.', answer='', resolved=False),
]

FOOD_GUIDE = [
  dict(title='How to tell a place is happy to have you', body='Green lights: a menu or prices visible outside, a ticket machine (ramen, soba, gyudon), plastic food models, a photo or English menu, a listing on Tabelog, staff who call “irasshaimase” when the door opens, and any yakiniku, okonomiyaki, udon or soba shop. Nozawa, Tenma, Fukushima, Tsuruhashi and Narai are all used to visitors; you are not intruding.'),
  dict(title='When to bow out', body='A sign reading 一見さんお断り (ichigen-san okotowari, “first-timers not accepted”) or 会員制 (members only); a tiny “snack” bar with a hostess and no price list; a six-seat counter where every seat is a regular and the master does not look up. Being turned away is not an insult: a small bow, “sumimasen”, and try the next door. That system is mostly Kyoto tea-house culture anyway; Osaka standing bars welcome anyone who orders a drink.'),
  dict(title='Manners that matter more than language', body='Order a drink first, then food. The small dish that arrives unasked (otoshi) is a cover charge, not a mistake. One drink and a couple of plates, then move on when it is crowded; angle your body to make room at a standing bar. Cash out, no tipping ever. No photos of other customers or the counter without a nod from the master. “Oishii” and “gochisosama deshita” (thanks for the meal) on the way out go a long way.'),
  dict(title='Onsen and ryokan', body='Shoes off at the genkan, slippers off on tatami. Ryokan dinner is at a set time; be there. In the bathhouses: wash sitting down before you get in, no towel in the water, no swimwear, quiet, no phones. Tattoos: Nozawa’s village bathhouses are relaxed but cover-up stickers are cheap insurance if you have visible ink.'),
]

STAYS_GUIDE = [
  dict(title='Why Booking.com looks empty', body='Booking.com carries maybe a third of Nozawa’s beds, and Japanese inns often list only twin rooms at a 2-person price, which makes a solo search show “sold out” or silly prices. Peak weeks (this is one) also get released to Japanese sites first.'),
  dict(title='Where the rooms actually are', body='1. Rakuten Travel (travel.rakuten.com, English) and Jalan: search with 1 adult; they show single-occupancy plans with meals. 2. Email the inn directly in short simple English: dates, one person, one room, ask the price with breakfast. Most reply within a day. 3. Nozawa Holidays (nozawaholidays.com) manages a dozen lodges and will answer one email with everything that still has a solo room. 4. Stay Nozawa and nozawaonsen.ski run request forms that go to several properties at once.'),
  dict(title='What to ask for', body='“1 person, single occupancy, 11-16 Feb, private room, breakfast included if possible.” Expect a supplement of 20-30% over the per-person twin rate. Shared bathrooms are normal and fine: you will be in the village bathhouses anyway.'),
  dict(title='If it is truly full', body='Togari Onsen is 20 minutes by bus across the valley and much quieter and cheaper; sleep there and bus to Nozawa for skiing. Or switch base to Akakura Onsen (Myoko), where several ryokan take single bookings on Rakuten; only the Nagano end of the plan changes. Iiyama Station has very little lodging, so do not count on it.'),
]


